#pragma once
// limbo/unicode.hpp — UTF-8 decoding and the Unicode character classes the pre-split needs.
//
// The class tables are generated by scripts/gen_unicode.py from Python's Unicode database: \p{L},
// \p{M}, \p{N} and the White_Space property. They are Unicode facts, not donor expression.

#include <cstdint>
#include <string>
#include <string_view>

namespace limbo::uni {

struct Range {
    uint32_t lo, hi;
};

extern const Range kLetter[];
extern const size_t kLetterCount;
extern const Range kMark[];
extern const size_t kMarkCount;
extern const Range kNumber[];
extern const size_t kNumberCount;
extern const Range kSpace[];
extern const size_t kSpaceCount;

bool in(const Range* ranges, size_t n, uint32_t cp);

inline bool is_letter(uint32_t cp) { return in(kLetter, kLetterCount, cp); }
inline bool is_mark(uint32_t cp) { return in(kMark, kMarkCount, cp); }
inline bool is_number(uint32_t cp) { return in(kNumber, kNumberCount, cp); }
inline bool is_space(uint32_t cp) { return in(kSpace, kSpaceCount, cp); }

// Decodes one codepoint at `at`. Returns its length in bytes (1..4). A malformed byte is reported as
// U+FFFD with length 1, so a caller always makes progress and never reads past the end.
size_t decode(std::string_view s, size_t at, uint32_t* cp);

// Appends cp as UTF-8.
void append_utf8(uint32_t cp, std::string& out);

}  // namespace limbo::uni
